## Code Example

```javascript
function stableSortIndicesByValue(A){
  const idx = Array.from({length: A.length}, (_, i) => i);
  function merge(left, right){
    const res = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length){
      if (A[left[i]] <= A[right[j]]) res.push(left[i++]);
      else res.push(right[j++]);
    }
    while (i < left.length) res.push(left[i++]);
    while (j < right.length) res.push(right[j++]);
    return res;
  }
  function sort(arr){
    if (arr.length <= 1) return arr;
    const m = Math.floor(arr.length / 2);
    const L = sort(arr.slice(0, m));
    const R = sort(arr.slice(m));
    return merge(L, R);
  }
  const P = sort(idx);
  return { P, sorted: P.map(i => A[i]) };
}
```

## Why This Is Asked

Begins with a classic DP pattern, forcing explicit memoization and tabulation, then space-optimized thinking.

## Key Concepts

- Dynamic programming, memoization, tabulation
- Base cases, overlapping subproblems
- Space optimization tricks

## Code Example

```javascript
function maxNonAdjacent(nums){
  const n = nums.length;
  const memo = new Array(n).fill(-1);
  const dfs = (i) => {
    if(i >= n) return 0;
    if(memo[i] !== -1) return memo[i];
    const take = nums[i] + dfs(i+2);
    const skip = dfs(i+1);
    memo[i] = Math.max(take, skip);
    return memo[i];
  };
  return dfs(0);
}
```

